import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.util.StringTokenizer;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);StringTokenizer st = new StringTokenizer(br.readLine());int t = Integer.parseInt(st.nextToken());while (t-- > 0) {st = new StringTokenizer(br.readLine());long n = Long.parseLong(st.nextToken());long k = Long.parseLong(st.nextToken());long ans = k + (k - 1) / (n - 1);out.println(ans);}out.flush();out.close();}}